using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Security.Principal;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;

internal sealed class UpdateFile {public string Path,Hash;public long Size;}
internal sealed class UpdateJob {
    public string Root,Stage,Version,InstalledHash;public int ParentPid;public long ParentStarted;public List<UpdateFile> Files=new List<UpdateFile>();
}
internal static class UpdateInstaller {
    internal static string UpdateHome {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aion2Helper","Updates");}}
    internal static string NewStage(){string stage=Path.Combine(UpdateHome,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);return stage;}
    internal static string Inside(string root,string relative){string full=Path.GetFullPath(Path.Combine(root,relative));if(!full.StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Update path is outside its folder.");return full;}
    internal static bool Allowed(string path){string p=path.Replace('\\','/');if(p.StartsWith("/",StringComparison.Ordinal)||p.IndexOf(':')>=0||p.IndexOf('\0')>=0)return false;foreach(string part in p.Split('/'))if(part.Length==0||part=="."||part==".."||part.EndsWith(".",StringComparison.Ordinal)||part.EndsWith(" ",StringComparison.Ordinal)||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0)return false;
        switch(p.ToLowerInvariant()){case "aion2helper.exe":case "aion-2-helper.cmd":case "readme.md":case "third-party.md":case "release-notes.md":case "assets/aion-2-helper.png":case "assets/aion-2-helper.ico":case "assets/sounds/party-invite.mp3":case "protocol/sync-opcodes.json":case "protocol/license-mit.txt":case "tools/presentmon/presentmon.exe":case "tools/presentmon/license.txt":case "tools/presentmon/third_party.txt":case "tools/presentmon/readme.md":case "assets/skills/license-mit.txt":case "assets/skills/readme.md":case "assets/npcs/license-mit.txt":case "assets/npcs/readme.md":case "assets/licenses/aion2protocolresearch-mit.txt":return true;default:return false;}
    }
    internal static void NoLinks(string root,string target){string current=Path.GetFullPath(target),stop=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar);while(current.Length>=stop.Length){if((File.Exists(current)||Directory.Exists(current))&&(File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Update folders cannot contain symbolic links or junctions.");if(current.TrimEnd(Path.DirectorySeparatorChar).Equals(stop,StringComparison.OrdinalIgnoreCase))break;current=Path.GetDirectoryName(current);if(current==null)break;}}
    internal static UpdateJob Stage(string archive,string stage,string root,Version version,UpdateCancellation cancellation){
        string payload=Inside(stage,"payload");Directory.CreateDirectory(payload);var job=new UpdateJob{Root=Path.GetFullPath(root),Stage=Path.GetFullPath(stage),Version=version.ToString(3),InstalledHash=UpdateManager.Hash(Path.Combine(root,"Aion2Helper.exe"))};using(var parent=Process.GetCurrentProcess()){job.ParentPid=parent.Id;job.ParentStarted=parent.StartTime.ToUniversalTime().Ticks;}
        long total=0;var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>128)throw new InvalidDataException("Update contains too many files.");foreach(var entry in zip.Entries){cancellation.Check();string path=entry.FullName.Replace('\\','/');if(path.EndsWith("/",StringComparison.Ordinal)){if(entry.Length!=0)throw new InvalidDataException("Invalid update directory.");string directory=path.TrimEnd('/');Inside(payload,directory);if(directory.IndexOf(':')>=0||directory.Split('/').Length>4)throw new InvalidDataException("Invalid update directory.");continue;}if(!Allowed(path)||!paths.Add(path)||((entry.ExternalAttributes>>16)&0xf000)==0xa000)throw new InvalidDataException("Unexpected or unsafe update file: "+path);total+=entry.Length;if(entry.Length<0||entry.Length>128L*1024*1024||total>256L*1024*1024)throw new InvalidDataException("Unpacked update is too large.");string target=Inside(payload,path);Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var buffer=new byte[65536];int n;long actual=0;while((n=input.Read(buffer,0,buffer.Length))>0){cancellation.Check();actual+=n;if(actual>entry.Length)throw new InvalidDataException("Invalid update file size.");output.Write(buffer,0,n);}if(actual!=entry.Length)throw new InvalidDataException("Incomplete update file.");}job.Files.Add(new UpdateFile{Path=path,Size=entry.Length,Hash=UpdateManager.Hash(target)});}}
        foreach(string required in new[]{"Aion2Helper.exe","protocol/sync-opcodes.json","tools/presentmon/PresentMon.exe","assets/sounds/party-invite.mp3"})if(!paths.Contains(required))throw new InvalidDataException("Update is missing required program files.");var assembly=AssemblyName.GetAssemblyName(Inside(payload,"Aion2Helper.exe"));if(assembly.Version.Major!=version.Major||assembly.Version.Minor!=version.Minor||assembly.Version.Build!=version.Build)throw new InvalidDataException("Downloaded application version does not match the release.");if(FileVersionInfo.GetVersionInfo(Inside(payload,"Aion2Helper.exe")).ProductName!="Aion 2 Helper")throw new InvalidDataException("Downloaded application is not Aion 2 Helper.");
        File.WriteAllText(Inside(stage,"job.json"),new JavaScriptSerializer().Serialize(job),new UTF8Encoding(false));return job;
    }
    internal static void Launch(UpdateJob job){string runner=Inside(job.Stage,"UpdateRunner.exe");File.Copy(Assembly.GetExecutingAssembly().Location,runner,false);bool elevated;using(var identity=WindowsIdentity.GetCurrent())elevated=new WindowsPrincipal(identity).IsInRole(WindowsBuiltInRole.Administrator);var start=new ProcessStartInfo(runner,"--apply-update \""+Inside(job.Stage,"job.json")+"\""){UseShellExecute=true,WorkingDirectory=job.Stage,WindowStyle=ProcessWindowStyle.Hidden};if(!elevated){string probe=Inside(job.Root,".update-write-"+Guid.NewGuid().ToString("N"));try{using(File.Create(probe)){}File.Delete(probe);}catch(UnauthorizedAccessException){start.Verb="runas";}}using(var process=Process.Start(start)){if(process==null)throw new IOException("Could not start the update installer.");}
    }
    internal static UpdateJob Load(string jobPath){if(new FileInfo(jobPath).Length>100000)throw new InvalidDataException("Invalid update job.");var job=new JavaScriptSerializer().Deserialize<UpdateJob>(File.ReadAllText(jobPath));if(job==null||job.Files==null||job.Files.Count<1||job.Files.Count>128||job.Stage==null||job.Root==null)throw new InvalidDataException("Invalid update job.");string expected=Path.Combine(Path.GetFullPath(job.Stage),"job.json");if(!Path.GetFullPath(jobPath).Equals(expected,StringComparison.OrdinalIgnoreCase)||!Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location).TrimEnd(Path.DirectorySeparatorChar).Equals(Path.GetFullPath(job.Stage).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(Path.GetDirectoryName(job.Stage)).Equals("Updates",StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(job.Stage).Equals(Path.GetFileNameWithoutExtension(job.Stage),StringComparison.Ordinal)||Path.GetFullPath(job.Root).TrimEnd(Path.DirectorySeparatorChar)==Path.GetPathRoot(job.Root).TrimEnd(Path.DirectorySeparatorChar))throw new InvalidDataException("Invalid update destination.");UpdateManager.ParseVersion(job.Version);return job;}
    internal static void WaitForParent(UpdateJob job,Action<int,string> progress){try{using(var parent=Process.GetProcessById(job.ParentPid)){if(parent.StartTime.ToUniversalTime().Ticks!=job.ParentStarted)return;string path=parent.MainModule.FileName;if(!Path.GetDirectoryName(path).TrimEnd(Path.DirectorySeparatorChar).Equals(job.Root.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Unexpected application process.");progress(0,"Waiting for Aion 2 Helper to close…");if(!parent.WaitForExit(60000))throw new IOException("The helper is still running. Close its other windows and try again.");}}catch(ArgumentException){}}
    // No recursive replacement: only the verified program-file allowlist is touched.
    // Every previous file is backed up before the first replacement.
    internal static void Apply(UpdateJob job,Action<int,string> progress,Action healthCheck,Action<int> fault=null){
        string payload=Inside(job.Stage,"payload"),backup=Inside(job.Stage,"previous");Directory.CreateDirectory(backup);var files=new List<UpdateFile>(job.Files);var unique=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var file in files){if(!Allowed(file.Path)||!unique.Add(file.Path)||file.Size<0||file.Size>128L*1024*1024)throw new InvalidDataException("Invalid installer file list.");string source=Inside(payload,file.Path),target=Inside(job.Root,file.Path);NoLinks(payload,source);NoLinks(job.Root,target);if(!File.Exists(source)||new FileInfo(source).Length!=file.Size||UpdateManager.Hash(source)!=file.Hash)throw new InvalidDataException("Staged update verification failed.");}
        string current=Inside(job.Root,"Aion2Helper.exe");if(UpdateManager.Hash(current)!=job.InstalledHash)throw new IOException("The installed helper changed during the download. Check for updates again.");
        foreach(string alias in new[]{"AionDash.exe","DashProbe.exe"})if(File.Exists(Inside(job.Root,alias))){string source=Inside(payload,"Aion2Helper.exe"),aliasSource=Inside(payload,alias);File.Copy(source,aliasSource,true);files.Add(new UpdateFile{Path=alias,Size=new FileInfo(source).Length,Hash=UpdateManager.Hash(source)});}
        var existed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var file in files){string target=Inside(job.Root,file.Path);NoLinks(job.Root,target);if(File.Exists(target)){var wait=Stopwatch.StartNew();while(true){try{using(new FileStream(target,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){}break;}catch(IOException){if(wait.Elapsed.TotalSeconds>=10)throw new IOException("A program file is still in use. Close other helper instances and try again.");Thread.Sleep(200);}}string destination=Inside(backup,file.Path);Directory.CreateDirectory(Path.GetDirectoryName(destination));File.Copy(target,destination,false);existed.Add(file.Path);}}
        var changed=new List<UpdateFile>();try{int index=0;foreach(var file in files){progress(5+index*80/files.Count,"Installing update…");string target=Inside(job.Root,file.Path);Directory.CreateDirectory(Path.GetDirectoryName(target));NoLinks(job.Root,target);if(fault!=null)fault(index);changed.Add(file);Replace(Inside(payload,file.Path),target);if(UpdateManager.Hash(target)!=file.Hash)throw new IOException("Installed file verification failed.");index++;}progress(90,"Checking the updated application…");healthCheck();File.WriteAllText(Inside(job.Stage,"result.json"),"{\"status\":\"installed\",\"version\":\""+job.Version+"\"}");}
        catch{var failures=new List<string>();changed.Reverse();foreach(var file in changed)try{string target=Inside(job.Root,file.Path);NoLinks(job.Root,target);if(existed.Contains(file.Path))Replace(Inside(backup,file.Path),target);else if(File.Exists(target))File.Delete(target);}catch(IOException){failures.Add(file.Path);}catch(UnauthorizedAccessException){failures.Add(file.Path);}File.WriteAllText(Inside(job.Stage,"result.json"),new JavaScriptSerializer().Serialize(new{status=failures.Count==0?"restored":"restore_failed",files=failures}));if(failures.Count>0)throw new IOException("Automatic restoration could not finish. Your previous program files are in: "+backup);throw;}
    }
    static void Replace(string source,string target){string temporary=target+".update-"+Guid.NewGuid().ToString("N");try{File.Copy(source,temporary,false);if(File.Exists(target))File.Replace(temporary,target,null);else File.Move(temporary,target);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
    internal static void Discard(string stage){if(stage==null)return;string full=Path.GetFullPath(stage);if(!full.StartsWith(Path.GetFullPath(UpdateHome)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(full),"^[a-f0-9]{32}$"))return;try{NoLinks(UpdateHome,full);if(Directory.Exists(full)&&!Directory.Exists(Path.Combine(full,"previous")))Directory.Delete(full,true);}catch(IOException){}catch(UnauthorizedAccessException){}}
    internal static void HealthCheck(string root){foreach(string file in new[]{"Aion2Helper.exe","protocol/sync-opcodes.json","tools/presentmon/PresentMon.exe","assets/sounds/party-invite.mp3"})if(!File.Exists(Inside(root,file)))throw new IOException("Missing required application file.");new JavaScriptSerializer().DeserializeObject(File.ReadAllText(Inside(root,"protocol/sync-opcodes.json")));}
    internal static void VerifyInstalled(UpdateJob job){var start=new ProcessStartInfo(Inside(job.Root,"Aion2Helper.exe"),"--update-health-check"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=job.Root,WindowStyle=ProcessWindowStyle.Hidden};using(var p=Process.Start(start)){if(!p.WaitForExit(15000)){p.Kill();throw new IOException("The updated helper did not pass its startup check.");}if(p.ExitCode!=0)throw new IOException("The updated helper failed its startup check.");}}
    internal static void Restart(UpdateJob job){Process.Start(new ProcessStartInfo(Inside(job.Root,"Aion2Helper.exe"),"--updated"){UseShellExecute=true,WorkingDirectory=job.Root,WindowStyle=ProcessWindowStyle.Hidden});}
}
